// Normalize incoming candidate application attributes
const item = $input.item.json;
const body = item.body || item;

function cleanPhone(ph) {
  if (!ph) return '';
  const digits = String(ph).replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('0')) return digits.slice(1);
  if (digits.length === 12 && digits.startsWith('91')) return digits.slice(2);
  return digits;
}

const normalizedEmail = (body.email || body.primary_email || '').trim().toLowerCase();
const normalizedPhone = cleanPhone(body.phone || body.primary_phone || '');
const canonicalName = (body.full_name || body.name || body.canonical_name || '').trim();

return {
  json: {
    raw_input: body,
    normalized_email: normalizedEmail,
    normalized_phone: normalizedPhone,
    canonical_name: canonicalName,
    city: body.city || body.canonical_city || '',
    skills: body.skills || [],
    experience_years: body.experience_years || 0
  }
};

// Cross-check normalized candidate against 60 Golden Persons database candidates
const normalizedInput = $("Code in JavaScript").first().json;
const candidatesList = $("HTTP Request").all().map(i => i.json);

let matchedCandidate = null;
let matchReason = '';

for (const cand of candidatesList) {
  const dbEmail = (cand.primary_email || '').trim().toLowerCase();
  const dbPhone = String(cand.primary_phone || '').replace(/\D/g, '');

  if (normalizedInput.normalized_email && dbEmail && dbEmail === normalizedInput.normalized_email) {
    matchedCandidate = cand;
    matchReason = `Exact Email Match (${dbEmail})`;
    break;
  }
  if (normalizedInput.normalized_phone && dbPhone && dbPhone === normalizedInput.normalized_phone) {
    matchedCandidate = cand;
    matchReason = `Exact Phone Match (${dbPhone})`;
    break;
  }
}

const isDuplicate = !!matchedCandidate;

return {
  json: {
    isDuplicate: isDuplicate,
    matchReason: matchReason,
    candidate_name: normalizedInput.canonical_name,
    email: normalizedInput.normalized_email,
    phone: normalizedInput.normalized_phone,
    existing_person_id: matchedCandidate ? matchedCandidate.id : null,
    matched_person_name: matchedCandidate ? matchedCandidate.canonical_name : null,
    status: isDuplicate ? 'DUPLICATE_ALERT' : 'NEW_CANDIDATE'
  }
};
